local function NS(k) local t = {} for i, p in k do t[i] = NumberSequenceKeypoint.new(p[1], p[2], p[3] or 0) end return NumberSequence.new(t) end
local function CS(k) local t = {} for i, p in k do t[i] = ColorSequenceKeypoint.new(p[1], Color3.fromHex(p[2])) end return ColorSequence.new(t) end

